package io.github.jhipster.sample.service;

import io.github.jhipster.sample.repository.OperationRepository;
import io.github.jhipster.sample.service.dto.OperationDTO;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class OperationService {

    private static final Duration RECENT_WINDOW = Duration.ofDays(30);

    private final OperationRepository operationRepository;

    private final Clock clock;

    public OperationService(OperationRepository operationRepository, Clock clock) {
        this.operationRepository = operationRepository;
        this.clock = clock;
    }

    @Transactional(readOnly = true)
    public List<OperationDTO> findRecent() {
        Instant now = Instant.now(clock);
        return operationRepository.findByDateBetween(now.minus(RECENT_WINDOW), now).stream().map(OperationDTO::from).toList();
    }
}
EOF
